// Auto-generated terrain map — 600x300 grid over SVG 1425x678
// Generated by pixel scan of map.svg — DO NOT EDIT MANUALLY
// Each character maps to a 5x5 sim-tile block
// O=ocean, h=highland, m=midland, l=lowland, M=mountain, L=lake/river, c=coast

export const SVG_W = 1425;
export const SVG_H = 678;

// Sim grid dimensions
const SIM_W = 3000;
const SIM_H = 1502;
const COAST_Y = 1499;
const VESSEL_Y_START = 1500;

// Verified SVG land bounds (from pixel scan)
const LAND_SVG_X_MIN = 70;
const LAND_SVG_X_MAX = 1281;
const LAND_SVG_Y_MIN = 41;
const LAND_SVG_Y_MAX = 565;
const VESSEL_SVG_Y = 668;

// Terrain grid: 600x300 chars, one per cell
// Row 0 = north (SVG top), Row 299 = south coast
export const TERRAIN_W = 600;
export const TERRAIN_H = 300;
export const TERRAIN: string = '';

// Legacy lookup — kept for compatibility
export const TILE_COORDS: [number, number][] = [];
export const VESSEL_COORDS: Record<number, [number, number]> = {
  30: [700, 655],
  31: [700, 668],
};

export function tileToSvg(tileX: number, tileY: number): [number, number] {
  // Vessel zone (at sea)
  if (tileY >= VESSEL_Y_START) {
    const svgX = LAND_SVG_X_MIN + (tileX / SIM_W) * (LAND_SVG_X_MAX - LAND_SVG_X_MIN);
    return [svgX, VESSEL_SVG_Y];
  }

  // Map sim coords proportionally to SVG space using verified land bounds
  const svgX = LAND_SVG_X_MIN + (tileX / SIM_W) * (LAND_SVG_X_MAX - LAND_SVG_X_MIN);
  const svgY = LAND_SVG_Y_MIN + (tileY / COAST_Y) * (LAND_SVG_Y_MAX - LAND_SVG_Y_MIN);
  return [svgX, svgY];
}

export function tileToTerrain(tileX: number, tileY: number): string {
  if (tileY >= VESSEL_Y_START) return 'O';
  const col = Math.min(TERRAIN_W - 1, Math.floor((tileX / SIM_W) * TERRAIN_W));
  const row = Math.min(TERRAIN_H - 1, Math.floor((tileY / COAST_Y) * TERRAIN_H));
  return TERRAIN[row * TERRAIN_W + col] ?? 'O';
}
